 View badge(String letter,int number,int color){LinearLayout pill=new LinearLayout(a);pill.setGravity(Gravity.CENTER_VERTICAL);pill.setPadding(Ui.dp(a,4),Ui.dp(a,3),Ui.dp(a,8),Ui.dp(a,3));pill.setBackground(shape((color&0x00ffffff)|0x19000000,16,0));TextView icon=text(letter,10,Color.WHITE,true);icon.setGravity(Gravity.CENTER);icon.setPadding(0,0,0,0);icon.setBackground(shape(color,20,0));pill.addView(icon,new LinearLayout.LayoutParams(Ui.dp(a,18),Ui.dp(a,18)));TextView count=text(" "+number+"일",12,color,true);pill.addView(count);return pill;}
 void badges(LinearLayout row,DashboardStats.Counts c,boolean header){if(c.observed==0){row.addView(text("미조회",11,Ui.MUTED,false));return;}int[] indexes=a.isAsiana()?new int[]{0,1}:new int[]{2,0,1},colors=a.isAsiana()?CarrierUi.colors(true):new int[]{GOLD,BLUE,ORANGE};String[] letters=a.isAsiana()?new String[]{"B","U"}:new String[]{"F","P","U"};boolean any=false;for(int i=0;i<indexes.length;i++)if(c.values[indexes[i]]>0){View badge=badge(letters[i],c.values[indexes[i]],colors[i]);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);if(header)p.bottomMargin=Ui.dp(a,3);else p.leftMargin=Ui.dp(a,4);row.addView(badge,p);any=true;}if(!any)row.addView(text("표식 없음",11,Ui.MUTED,false));}
 void region(String region,JSONArray cities,int index)throws Exception{
  LinearLayout card=new LinearLayout(a);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(Ui.dp(a,12),Ui.dp(a,10),Ui.dp(a,12),Ui.dp(a,10));card.setBackground(shape(Color.WHITE,15,Color.rgb(213,228,228)));card.setElevation(Ui.dp(a,1));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.bottomMargin=Ui.dp(a,13);body.addView(card,cp);
  LinearLayout header=new LinearLayout(a);header.setGravity(Gravity.CENTER_VERTICAL);header.setMinimumHeight(Ui.dp(a,66));View accent=new View(a);accent.setBackground(shape(CarrierUi.accent(a.isAsiana()),3,0));header.addView(accent,new LinearLayout.LayoutParams(Ui.dp(a,4),Ui.dp(a,38)));LinearLayout labels=new LinearLayout(a);labels.setOrientation(LinearLayout.VERTICAL);labels.setPadding(Ui.dp(a,12),0,Ui.dp(a,5),0);labels.addView(text(region.replace("/","·"),17,Color.rgb(35,39,48),true));int eligible=RegionBatch.create(origin,region,a.catalog(),Search.today(),System.currentTimeMillis(),Search.lastDate(a.isAsiana()),a.carrierCode()).getJSONArray("queries").length();labels.addView(text("목록 "+cities.length()+"공항 · 조회 "+eligible+"개 노선·월",11,Ui.MUTED,false));header.addView(labels,new LinearLayout.LayoutParams(0,-2,1));LinearLayout totals=new LinearLayout(a);totals.setOrientation(LinearLayout.HORIZONTAL);badges(totals,stats.region(cities),false);header.addView(totals);TextView arrow=text("▾",19,Ui.MUTED,false);arrow.setGravity(Gravity.CENTER);header.addView(arrow,new LinearLayout.LayoutParams(Ui.dp(a,29),-2));card.addView(header);
  LinearLayout expanded=new LinearLayout(a);expanded.setOrientation(LinearLayout.VERTICAL);boolean open=true;expanded.setVisibility(open?View.VISIBLE:View.GONE);arrow.setText(open?"▴":"▾");header.setContentDescription(region+" 지역 펼치기");header.setOnClickListener(v->{boolean show=expanded.getVisibility()!=View.VISIBLE;expanded.setVisibility(show?View.VISIBLE:View.GONE);arrow.setText(show?"▴":"▾");});
  LinearLayout actions=new LinearLayout(a);if(BuildConfig.SCANNER&&cities.length()>0)actions.addView(button("양방향 조회",v->a.startRegion(region)),new LinearLayout.LayoutParams(0,-2,1));actions.addView(button("도시 목록",v->a.browseRegion(region)),new LinearLayout.LayoutParams(0,-2,1));expanded.addView(actions);expanded.addView(text(BuildConfig.SCANNER?"공유 자료 먼저 확인 · 오늘 수집 자료 재사용":"저장된 달력 · 앱 실행 시 자동 불러오기",10,Ui.MUTED,false));
  expanded.addView(text("집계 기간: "+Search.today()+" ~ "+Search.lastDate(a.isAsiana())+" · 양방향",11,Ui.MUTED,false));
  java.util.List<JSONObject> sorted=new java.util.ArrayList<>();for(int i=0;i<cities.length();i++)sorted.add(cities.getJSONObject(i));sorted.sort((x,y)->{int xc=stats.totalMarks(x.optString("code")),yc=stats.totalMarks(y.optString("code"));return xc!=yc?Integer.compare(yc,xc):x.optString("code").compareTo(y.optString("code"));});for(JSONObject city:sorted){String code=city.getString("code"),name=city.getString("name");if(code.equals(origin))continue;DashboardStats.Counts coverage=stats.airport(code);LinearLayout route=new LinearLayout(a);route.setGravity(Gravity.CENTER_VERTICAL);route.setMinimumHeight(Ui.dp(a,57));route.setPadding(Ui.dp(a,12),Ui.dp(a,7),Ui.dp(a,9),Ui.dp(a,7));route.setBackground(shape(Color.rgb(250,250,253),12,Color.rgb(229,230,237)));LinearLayout.LayoutParams rp=new LinearLayout.LayoutParams(-1,-2);rp.topMargin=Ui.dp(a,8);expanded.addView(route,rp);TextView airport=text(code,16,Color.rgb(34,38,46),true);route.addView(airport);TextView cityName=text("  "+name,11,Ui.MUTED,false);cityName.setSingleLine(true);cityName.setEllipsize(TextUtils.TruncateAt.END);route.addView(cityName,new LinearLayout.LayoutParams(0,-2,1));LinearLayout marks=new LinearLayout(a);marks.setGravity(Gravity.CENTER_VERTICAL);badges(marks,coverage,false);route.addView(marks);route.addView(text("  ›",18,Ui.MUTED,false));route.setContentDescription(code+" "+name+" 양방향 달력");route.setOnClickListener(v->openAirport(code,name));JSONObject target=new JSONObject().put("carrier",a.carrierCode()).put("origin",origin).put("destination",code).put("round",true);int expected=Search.collectionQueries(target).size();TextView detail=text("저장 "+coverage.months+"개 노선·월 · 조회 대상 "+expected+"개"+(expected==0?" · 조회 제외 · 저장 달력 유지":"")+" · 확인 "+coverage.observed+"일"+"\n최근 수집: "+(coverage.latest==0?"없음":DataTimes.at(coverage.latest)),10,Ui.MUTED,false);detail.setPadding(Ui.dp(a,12),0,0,Ui.dp(a,4));expanded.addView(detail);}
  card.addView(expanded);
 }
 void openAirport(String code,String name){try{LocalDate start=Search.today(),end=Search.lastDate(a.isAsiana());JSONObject s=new JSONObject().put("carrier",a.carrierCode()).put("origin",origin).put("destination",code).put("originName",origin).put("destinationName",name).put("start",start.toString()).put("end",end.toString()).put("round",true).put("returnStart",start.toString()).put("returnEnd",end.toString()).put("adults",1).put("children",0).put("infants",0).put("cabin",2).put("seatView",0);a.showResults(s);}catch(Exception e){Ui.message(a,"달력 오류",e.getMessage());}}
